    76	// Resolves one request to a response. Kept apart from the http server so
    77	// tests can call it directly.
    78	export async function handle(url, { dataDir } = {}) {
    79	  const { pathname, searchParams } = new URL(url, 'http://harbor.local');
    80	  if (pathname.startsWith('/public/')) return serveStatic(pathname.slice('/public/'.length));
    81	  const route = ROUTES[pathname];
    82	  if (!route) return page(404, 'Not found', '<h1>Not found</h1>', pathname);
    83	  let snapshot;
    84	  try {
    85	    snapshot = await readSnapshot(route.snapshot, dataDir);
    86	  } catch {
    87	    // The pipeline rewrites snapshots in place, so a read can fail for a
    88	    // moment. Say so instead of crashing; the next refresh usually works.
    89	    const body = `<h1>${escapeHtml(route.title)}</h1>
    90	<p class="muted">Snapshot unavailable, try again in a minute.</p>`;
    91	    return page(503, route.title, body, pathname);
    92	  }
    93	  return page(200, route.title, route.render(snapshot, Object.fromEntries(searchParams)), pathname);
    94	}
