=== src/shared/freshness.js
     1	// The pipeline writes every snapshot each minute. Five minutes without a new
     2	// one means a job is failing, which tools/verify and the overview report.
     3	export const STALE_AFTER_MS = 5 * 60_000;
     4	
     5	export function isStale(generatedAt, now, staleAfterMs = STALE_AFTER_MS) {
     6	  const written = Date.parse(generatedAt);
     7	  return Number.isNaN(written) || now - written > staleAfterMs;
     8	}

